const q = $input.first().json.query || {};
// Estado del cobro real. Si n8n bloquea el acceso a $env no se puede saber si
// Stripe está activo, y adivinar sería abrir de nuevo S2: se falla cerrado.
let stripeConfigurado;
try {
  stripeConfigurado = (typeof $env !== 'undefined' && $env) ? Boolean($env.STRIPE_SECRET_KEY) : false;
} catch (e) {
  throw new Error('No se puede leer STRIPE_SECRET_KEY: n8n tiene bloqueado el acceso al entorno en los nodos Code. Configurar N8N_BLOCK_ENV_ACCESS_IN_NODE=false (ver docker-compose.yml) para habilitar el modo de desarrollo.');
}
if (stripeConfigurado) throw new Error('Modo de desarrollo deshabilitado: hay credenciales de Stripe configuradas');
if (!q.factura_id) throw new Error('Falta factura_id');
// pago_token (S1 de la Tabla 11, cerrada): sin él, factura_id solo (10.000
// combinaciones adivinables por año) alcanzaba para marcar cualquier
// factura como cobrada. Se verifica contra la base en el próximo nodo.
if (!q.pago_token) throw new Error('Falta pago_token');
return [{ json: { factura_id: q.factura_id, pago_token: q.pago_token, lead_id: q.lead_id || '' } }];

