const item = $input.first().json.body || {};
const capitalizar = (s) => s.replace(/\S+/gu, (w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase());
const nombre = capitalizar((item.nombre || '').trim().replace(/\s+/g, ' '));
const email = (item.email || '').toLowerCase().trim();
function parsearImporte(valor) {
  if (typeof valor === 'number') return Number.isFinite(valor) ? valor : NaN;
  if (typeof valor !== 'string') return NaN;
  const limpio = valor.trim().replace(/^[^0-9.,-]+/, '');
  if (!/^-?[0-9]+([.,][0-9]+)?$|^-?[0-9]{1,3}([.,][0-9]{3})*([.,][0-9]+)?$/.test(limpio)) return NaN;
  const sep = Math.max(limpio.lastIndexOf(','), limpio.lastIndexOf('.'));
  const normalizado = sep === -1 ? limpio : limpio.slice(0, sep).replace(/[.,]/g, '') + '.' + limpio.slice(sep + 1);
  const n = Number(normalizado);
  return Number.isFinite(n) ? n : NaN;
}
// El formulario manda un rango (presupuesto_rango) desde el 24-sep-2026; el
// importe que usa el scoring es el piso del rango, que coincide con sus cortes
// (300/1000/2000/5000). «Menos de 300» no tiene piso positivo y va como 100.
// Sin rango (otras vías, pedidos viejos), sigue valiendo el importe suelto.
const PISO_POR_RANGO = { hasta_300: 100, '300_1000': 300, '1000_2000': 1000, '2000_5000': 2000, mas_5000: 5000 };
const rangoPedido = String(item.presupuesto_rango || '').trim();
const presupuesto_rango = Object.prototype.hasOwnProperty.call(PISO_POR_RANGO, rangoPedido) ? rangoPedido : '';
const presupuesto = presupuesto_rango ? PISO_POR_RANGO[presupuesto_rango] : parsearImporte(item.presupuesto);
const urg = ['alta', 'media', 'baja'];
const urgencia = urg.includes((item.urgencia || '').toLowerCase()) ? item.urgencia.toLowerCase() : 'media';
const svcMap = { 'desarrollo web':'desarrollo_web','e-commerce':'ecommerce','ecommerce':'ecommerce','app móvil':'app_movil','app movil':'app_movil','app_movil':'app_movil','diseño ux/ui':'diseno_ui','diseno ux/ui':'diseno_ui','marketing digital':'marketing','seo / posicionamiento':'seo','seo/posicionamiento':'seo','automatización de procesos':'automatizacion','automatizacion de procesos':'automatizacion','automatizacion':'automatizacion','consultoría':'consultoria','consultoria':'consultoria','otro':'consultoria','soporte':'soporte','desarrollo_web':'desarrollo_web','diseno_ui':'diseno_ui','marketing':'marketing','seo':'seo' };
const servicio = svcMap[(item.servicio || '').toLowerCase().trim()] || 'consultoria';
const errores = [];
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) errores.push('email invalido');
if (nombre.length < 2) errores.push('nombre muy corto');
// El nombre aparece tal cual en el acuse que se manda al email del formulario:
// sin tope ni filtro de enlaces, alcanzaba para usar ese correo como spam.
if (nombre.length > 100) errores.push('nombre muy largo');
if (/:\/\/|www\./i.test(nombre)) errores.push('nombre con enlace');
if (!Number.isFinite(presupuesto) || presupuesto <= 0) errores.push('presupuesto invalido');
if (rangoPedido && !presupuesto_rango) errores.push('rango invalido');
// Honeypot: un campo que el formulario esconde y una persona nunca completa.
if (String(item.sitio_web || '').trim()) errores.push('honeypot');
// Espacio del desarrollador al que va el pedido: lo manda el formulario de
// /f/<slug>. Vacío = el formulario de la raíz, que va al espacio del admin
// (transitorio, ver leads_espacio_por_defecto en db/schema.sql). Un valor que
// no tiene el formato de una dirección se rechaza en vez de caer ahí.
const espacio = String(item.espacio || '').toLowerCase().trim();
if (espacio && !/^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$/.test(espacio)) errores.push('espacio invalido');
if (errores.length) throw new Error('Validacion fallida: ' + errores.join(', '));
const ts = Date.now();
const azar = () => {
  try {
    return require('crypto').randomBytes(5).toString('hex').toUpperCase();
  } catch (e) {
    return Math.random().toString(36).substring(2, 10).toUpperCase();
  }
};
return [{ json: { lead_id: 'LD-' + ts + '-' + azar(), nombre, email, presupuesto, presupuesto_rango, compartir_bolsa: item.compartir_bolsa === true, urgencia, servicio, telefono: (item.telefono || '').trim(), descripcion: (item.descripcion || '').trim().substring(0, 2000), fuente: item.fuente || 'webhook', espacio } }];

// Calificación del lead. Los pesos y los umbrales de tier NO son constantes
// de código: salen de variables de entorno, de modo que el criterio de
// calificación se puede recalibrar sin tocar el workflow (§6, cuestión 3 del
// dictamen). Los defaults reproducen exactamente la Tabla 4 de la tesis.
const leerEnv = (clave, porDefecto) => {
  try {
    const v = (typeof $env !== 'undefined' && $env) ? $env[clave] : undefined;
    return (v === undefined || v === null || v === '') ? porDefecto : String(v);
  } catch (e) { return porDefecto; }
};
// "umbral:puntos,umbral:puntos" evaluado de mayor a menor.
const tramos = (clave, porDefecto) => leerEnv(clave, porDefecto)
  .split(',')
  .map((p) => p.split(':'))
  .map(([k, v]) => [Number(k), Number(v)])
  .filter(([k, v]) => Number.isFinite(k) && Number.isFinite(v))
  .sort((a, b) => b[0] - a[0]);
// "clave:puntos,clave:puntos"
const tabla = (clave, porDefecto) => Object.fromEntries(
  leerEnv(clave, porDefecto)
    .split(',')
    .map((p) => p.split(':'))
    .filter((p) => p.length === 2)
    .map(([k, v]) => [String(k).trim(), Number(v)])
);

const l = $input.first().json;
let score = 0;

function parsearImporte(valor) {
  if (typeof valor === 'number') return Number.isFinite(valor) ? valor : NaN;
  if (typeof valor !== 'string') return NaN;
  const limpio = valor.trim().replace(/^[^0-9.,-]+/, '');
  if (!/^-?[0-9]+([.,][0-9]+)?$|^-?[0-9]{1,3}([.,][0-9]{3})*([.,][0-9]+)?$/.test(limpio)) return NaN;
  const sep = Math.max(limpio.lastIndexOf(','), limpio.lastIndexOf('.'));
  const normalizado = sep === -1 ? limpio : limpio.slice(0, sep).replace(/[.,]/g, '') + '.' + limpio.slice(sep + 1);
  const n = Number(normalizado);
  return Number.isFinite(n) ? n : NaN;
}
const presupuestoParsed = parsearImporte(l.presupuesto);
const presupuesto = Number.isFinite(presupuestoParsed) ? presupuestoParsed : 0;
for (const [minimo, puntos] of tramos('SCORING_PRESUPUESTO', '5000:40,2000:30,1000:20,300:10')) {
  if (presupuesto >= minimo) { score += puntos; break; }
}

const porUrgencia = tabla('SCORING_URGENCIA', 'alta:30,media:15,baja:5');
score += porUrgencia[l.urgencia] !== undefined ? porUrgencia[l.urgencia] : Number(leerEnv('SCORING_URGENCIA_DEFAULT', '5'));

const porServicio = tabla('SCORING_SERVICIO', 'desarrollo_web:20,ecommerce:20,app_movil:18,automatizacion:18,marketing:15,seo:15,diseno_ui:15,consultoria:12,soporte:5');
score += porServicio[l.servicio] !== undefined ? porServicio[l.servicio] : Number(leerEnv('SCORING_SERVICIO_DEFAULT', '8'));

if (l.telefono && l.telefono.length > 6) score += Number(leerEnv('SCORING_BONUS_TELEFONO', '5'));
if (l.descripcion && l.descripcion.length > 50) score += Number(leerEnv('SCORING_BONUS_DESCRIPCION', '5'));

const umbralHot = Number(leerEnv('SCORING_UMBRAL_HOT', '70'));
const umbralWarm = Number(leerEnv('SCORING_UMBRAL_WARM', '40'));
const tier = score >= umbralHot ? 'HOT' : score >= umbralWarm ? 'WARM' : 'COLD';

return [{ json: Object.assign({}, l, { score: score, tier: tier }) }];

// Todo dato que se interpola en el HTML pasa por esc(): nombre, email, etc. los
// escribe quien completa el formulario público, y sin escapar alcanzaba para
// inyectar HTML en el correo o en el PDF que renderiza Gotenberg.
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const l = $input.first().json;
// La plataforma es compartida: cada correo sale con el nombre del espacio del
// desarrollador que atiende el pedido. Sin espacio, el de la plataforma.
const marca = String(l.espacio_nombre || '').trim() || (() => {
  try { return (typeof $env !== 'undefined' && $env && $env.PLATAFORMA_NOMBRE) || 'FormularioLeads'; } catch (e) { return 'FormularioLeads'; }
})();
const primerNombre = String(l.nombre || 'Cliente').split(' ')[0];
const svc = String(l.servicio || 'servicio').replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
// El plazo, el precio y el alcance los fija el profesional al enviar la
// propuesta. El respaldo por urgencia queda sólo para las propuestas
// anteriores a que esa función existiera.
const tiempo = String(l.plazo_propuesto || '').trim() || ((l.urgencia === 'alta') ? '3-5 dias habiles' : '1-2 semanas');
const precio = Number(l.precio_propuesto) > 0 ? Number(l.precio_propuesto) : Number(l.presupuesto) || 0;
const alcance = esc(String(l.alcance_propuesto || '').trim()).replace(/\n/g, '<br>');
const leerEnv = (clave, porDefecto) => {
  try {
    const v = (typeof $env !== 'undefined' && $env) ? $env[clave] : undefined;
    return (v === undefined || v === null || v === '') ? porDefecto : String(v);
  } catch (e) { return porDefecto; }
};
// URL pública del front. Se configura con FRONTEND_URL (ver .env.example).
const FRONT_BASE = leerEnv('FRONTEND_URL', 'http://localhost:3000').replace(/\/+$/, '');
const acceptUrl = FRONT_BASE + '/aceptar/' + encodeURIComponent(l.lead_id) + '?token=' + encodeURIComponent(l.accept_token);
const html = `<!DOCTYPE html><html><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width,initial-scale=1'></head><body style='margin:0;background:#f4f4f5;font-family:Arial,Helvetica,sans-serif;color:#27272a'><div style='max-width:600px;margin:0 auto;background:#ffffff'><div style='background:#111827;padding:32px 40px'><div style='color:#fbbf24;font-size:20px;font-weight:800;letter-spacing:1px'>${esc(marca.toUpperCase())}</div><div style='color:#9ca3af;font-size:12px;letter-spacing:2px;text-transform:uppercase;margin-top:4px'>Propuesta de trabajo</div></div><div style='padding:40px'><p style='font-size:16px;margin:0 0 8px'>Hola <b>${esc(primerNombre)}</b>,</p><p style='font-size:15px;line-height:1.6;color:#52525b;margin:0 0 28px'>Gracias por tu interes. Preparamos una propuesta para tu proyecto de <b>${esc(svc)}</b>:</p><table style='width:100%;border-collapse:collapse;margin:0 0 28px'><tr><td style='padding:14px 0;border-bottom:1px solid #e4e4e7;color:#71717a;font-size:13px'>Servicio</td><td style='padding:14px 0;border-bottom:1px solid #e4e4e7;text-align:right;font-weight:700'>${esc(svc)}</td></tr>${alcance ? "<tr><td style='padding:14px 0;border-bottom:1px solid #e4e4e7;color:#71717a;font-size:13px;vertical-align:top'>Alcance</td><td style='padding:14px 0;border-bottom:1px solid #e4e4e7;text-align:right;line-height:1.5'>" + alcance + '</td></tr>' : ''}<tr><td style='padding:14px 0;border-bottom:1px solid #e4e4e7;color:#71717a;font-size:13px'>Tiempo de entrega</td><td style='padding:14px 0;border-bottom:1px solid #e4e4e7;text-align:right;font-weight:700'>${esc(tiempo)}</td></tr><tr><td style='padding:14px 0;color:#71717a;font-size:13px'>Inversion</td><td style='padding:14px 0;text-align:right;font-weight:800;font-size:18px;color:#111827'>${esc(precio)} USD</td></tr></table><div style='text-align:center;margin:0 0 24px'><a href='${esc(acceptUrl)}' style='display:inline-block;background:#fbbf24;color:#111827;padding:16px 40px;border-radius:8px;text-decoration:none;font-weight:800;font-size:15px'>Ver propuesta y responder</a></div><p style='font-size:13px;line-height:1.6;color:#a1a1aa;text-align:center;margin:0'>Desde el enlace vas a poder <b>aceptar</b>, <b>pedir cambios</b> o <b>rechazar</b> la propuesta.</p></div><div style='background:#fafafa;padding:24px 40px;border-top:1px solid #e4e4e7'><p style='margin:0;font-size:13px;color:#71717a'>Saludos,<br><b style='color:#27272a'>${esc(marca)}</b></p></div></div></body></html>`;
return [{ json: Object.assign({}, l, { propuesta_html: html, accept_url: acceptUrl }) }];

