const b = $input.first().json.body || {};
if (!b.lead_id || !b.token) throw new Error('Faltan parametros');
return [{ json: { lead_id: b.lead_id, token: b.token } }];

// §4.3.2: antes esta rama sólo distinguía "válido" de "ya utilizado", y ese
// segundo cajón mezclaba cuatro desenlaces distintos (token ya usado, lead
// expirado/PERDIDO, token rotado por reenvío, token inexistente). Ahora la
// consulta anterior trae el lead SOLO por lead_id (sin filtrar por token ni
// vigencia) para poder clasificar el motivo con estas columnas.
const fila = $input.first().json || {};
const enviado = $('Code - Validar Token').first().json || {};
const leadId = fila.lead_id || enviado.lead_id;
const tokenEnviado = enviado.token;
const encontrado = !!fila.lead_id;
const estado = fila.estado;
const tokenCoincide = encontrado && fila.accept_token != null &&
  String(fila.accept_token) === String(tokenEnviado);
const tokenVencido = tokenCoincide && !!fila.token_expira_en &&
  new Date(fila.token_expira_en) <= new Date();

let categoria;
if (!encontrado) {
  // lead_id inexistente: no hay nada que clasificar.
  categoria = 'invalido';
} else if (estado === 'PERDIDO' || tokenVencido) {
  // el lead agotó los seguimientos (PERDIDO) o el token venció por tiempo
  // antes de que el cron llegara a marcarlo: en los dos casos la oportunidad
  // ya no está vigente, aunque el enlace nunca se haya "usado".
  categoria = 'expirado';
} else if (!tokenCoincide && estado !== 'NUEVO') {
  // el lead existe y ya tuvo una propuesta, pero el token que llegó no es el
  // vigente: la propuesta se reenvió (pedido de cambios o seguimiento) y
  // accept_token rotó (ver docs §5.1.1).
  categoria = 'rotado';
} else if (tokenCoincide && (estado === 'ACEPTADO' || estado === 'FACTURADO')) {
  // caso legítimo: este mismo token ya disparó la aceptación antes.
  categoria = 'ya_procesado';
} else if (tokenCoincide && (estado === 'PROPUESTA_ENVIADA' || estado === 'EN_SEGUIMIENTO')) {
  categoria = 'valido';
} else {
  categoria = 'invalido';
}

return [{ json: Object.assign({}, fila, { lead_id: leadId, token: tokenEnviado, categoria }) }];

// Todo dato que se interpola en el HTML pasa por esc(): nombre, email, etc. los
// escribe quien completa el formulario público, y sin escapar alcanzaba para
// inyectar HTML en el correo o en el PDF que renderiza Gotenberg.
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const l = $input.first().json;
// La plataforma es compartida: cada correo sale con el nombre del espacio del
// desarrollador que atiende el pedido. Sin espacio, el de la plataforma.
const marca = String(l.espacio_nombre || '').trim() || (() => {
  try { return (typeof $env !== 'undefined' && $env && $env.PLATAFORMA_NOMBRE) || 'FormularioLeads'; } catch (e) { return 'FormularioLeads'; }
})();
const payUrl = l.payUrl;
const svc = String(l.servicio || 'servicio').replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
const hoy = new Date().toLocaleDateString('es-AR');
const venc = new Date(l.fecha_vencimiento_iso).toLocaleDateString('es-AR');
const html = `<!DOCTYPE html><html><head><meta charset='UTF-8'></head><body style='font-family:Arial,Helvetica,sans-serif;padding:48px;color:#27272a'><div style='display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #111827;padding-bottom:24px'><div><div style='font-size:22px;font-weight:800;color:#111827;letter-spacing:1px'>${esc(marca.toUpperCase())}</div>${l.espacio_email ? "<div style='color:#71717a;font-size:13px;margin-top:4px'>" + esc(l.espacio_email) + '</div>' : ''}</div><div style='text-align:right'><div style='font-size:24px;font-weight:800;color:#fbbf24'>FACTURA</div><div style='font-size:13px;color:#71717a;margin-top:6px'>N ${esc(l.factura_id)}</div><div style='font-size:13px;color:#71717a'>Emisión: ${esc(hoy)}</div><div style='font-size:13px;color:#71717a'>Vence: ${esc(venc)}</div></div></div><p style='margin:24px 0;font-size:14px'><b>Cliente:</b> ${esc(l.nombre)}<br><b>Email:</b> ${esc(l.email)}</p><table style='width:100%;border-collapse:collapse;margin:0 0 24px'><tr style='background:#111827;color:#fff'><th style='padding:12px;text-align:left;font-size:13px'>Descripción</th><th style='padding:12px;font-size:13px'>Cant.</th><th style='padding:12px;text-align:right;font-size:13px'>Total</th></tr><tr><td style='padding:12px;border-bottom:1px solid #e4e4e7'>${esc(svc)}</td><td style='padding:12px;border-bottom:1px solid #e4e4e7;text-align:center'>1</td><td style='padding:12px;border-bottom:1px solid #e4e4e7;text-align:right'>$${esc(l.monto)}</td></tr><tr style='font-weight:800;background:#fafafa'><td colspan='2' style='padding:12px;text-align:right'>TOTAL</td><td style='padding:12px;text-align:right;font-size:18px'>${esc(l.monto)} ${esc(l.moneda)}</td></tr></table><div style='text-align:center;margin:28px 0'><a href='${esc(payUrl)}' style='display:inline-block;background:#fbbf24;color:#111827;padding:14px 36px;border-radius:8px;text-decoration:none;font-weight:800'>💳 Pagar ahora</a></div><div style='background:#f8fafc;border-left:4px solid #111827;padding:16px;font-size:13px'>El pago se hace desde el botón de arriba. Ante cualquier duda, respondé este correo.</div></body></html>`;
const b64 = Buffer.from(html, 'utf8').toString('base64');
return [{ json: l, binary: { factura_html_file: { data: b64, mimeType: 'text/html', fileName: 'index.html', fileExtension: 'html' } } }];

