const e = $input.first().json;
const ex = e.execution || {};
const msg = (ex.error && ex.error.message) || 'desconocido';
const nodo = ex.lastNodeExecuted || 'desconocido';
const wf = (e.workflow && e.workflow.name) || 'desconocido';
// Enmascara cualquier UUID (accept_token, pago_token, mp_payment_id, etc.)
// que pudiera colarse en el mensaje de un error de Postgres o de
// validación, para que un token de aceptación nunca quede en claro en la
// tabla de auditoría (Tabla 11, remanente de S3): sólo quedan los primeros
// 8 caracteres + …
const enmascarar = (s) => String(s).replace(
  /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi,
  (m) => m.slice(0, 8) + '…',
);
return [{ json: { wf_origen: wf, evento: 'ERROR_CRITICO', nivel: 'ERROR', detalle: enmascarar('Nodo: ' + nodo), error_msg: enmascarar(String(msg).substring(0, 300)) } }];

