// §4.3.2: la misma ambigüedad de /lead-acepta existía acá, que es lo que
// carga la pantalla ANTES de que el cliente llegue a tocar 'Aceptar'. La
// consulta anterior trae el lead SOLO por lead_id (sin filtrar por token ni
// vigencia) para poder distinguir el motivo con estas columnas.
const rows = $input.all();
const r = rows.length ? rows[0].json : null;
const enviado = $('Code - Leer Query').first().json || {};
const tokenEnviado = enviado.token;

if (!r || !r.lead_id) {
  return [{ json: { status: 'invalido', motivo: 'invalido', mensaje: 'Enlace no válido o vencido.' } }];
}

const tokenCoincide = r.accept_token != null && String(r.accept_token) === String(tokenEnviado);
const tokenVencido = tokenCoincide && !!r.token_expira_en && new Date(r.token_expira_en) <= new Date();

if (r.estado === 'PERDIDO' || tokenVencido) {
  return [{ json: { status: 'ya_procesado', motivo: 'expirado', mensaje: 'Esta oportunidad ya no está vigente: se agotaron los seguimientos y la propuesta caducó. Escribinos si todavía te interesa y coordinamos una nueva.' } }];
}

if (!tokenCoincide && r.estado !== 'NUEVO') {
  return [{ json: { status: 'ya_procesado', motivo: 'rotado', mensaje: 'Este enlace ya no es válido: se generó una versión más reciente de la propuesta. Revisá tu email por el último correo que te enviamos.' } }];
}

if (tokenCoincide && (r.estado === 'ACEPTADO' || r.estado === 'FACTURADO')) {
  return [{ json: { status: 'ya_procesado', motivo: 'token_usado', mensaje: 'Esta propuesta ya fue aceptada anteriormente. Ya deberías tener la factura en tu email.' } }];
}

const activos = ['PROPUESTA_ENVIADA', 'EN_SEGUIMIENTO'];
if (!tokenCoincide || !activos.includes(r.estado)) {
  return [{ json: { status: 'invalido', motivo: 'invalido', mensaje: 'Enlace no válido o vencido.' } }];
}
// La pagina de aceptacion mostraba solo nombre, servicio y presupuesto, es
// decir los tres datos que el propio cliente habia cargado en el formulario:
// aceptaba una propuesta que esa pantalla no le mostraba. Se devuelven los
// terminos que fijo el profesional, que son los que la propuesta compromete.
const precio = Number(r.precio_propuesto) > 0 ? Number(r.precio_propuesto) : Number(r.presupuesto) || 0;
const plazo = String(r.plazo_propuesto || '').trim() || ((r.urgencia === 'alta') ? '3-5 dias habiles' : '1-2 semanas');
return [{ json: { status: 'ok', lead: {
  nombre: r.nombre,
  servicio: r.servicio,
  presupuesto: Number(r.presupuesto),
  precio: precio,
  plazo: plazo,
  alcance: String(r.alcance_propuesto || '').trim(),
} } }];

