const b = $input.first().json.body || {};
if (!b.lead_id) throw new Error('Falta lead_id');
const precio = Number(b.precio);
if (!Number.isFinite(precio) || precio <= 0) throw new Error('El precio de la propuesta tiene que ser mayor que cero');
// Plazo y alcance son texto libre del profesional: se recortan, no se inventan.
const plazo = String(b.plazo || '').trim().substring(0, 120);
const alcance = String(b.alcance || '').trim().substring(0, 2000);
return [{ json: { lead_id: b.lead_id, precio: precio, plazo: plazo, alcance: alcance } }];

// Reconciliación (S5): arma la factura que la rama de aceptación no llegó a
// persistir. Toma UN lead por corrida (la consulta trae LIMIT 1), igual que el
// resto de la cadena de facturación, que también razona sobre un ítem.
const l = $input.first().json;
const leerEnv = (clave, porDefecto) => {
  try {
    const v = (typeof $env !== 'undefined' && $env) ? $env[clave] : undefined;
    return (v === undefined || v === null || v === '') ? porDefecto : String(v);
  } catch (e) { return porDefecto; }
};
// El identificador es DETERMINISTA a partir del lead: dos corridas del cron
// producen el mismo `factura_id`, de modo que la restricción UNIQUE de la
// columna es una segunda red por debajo del `WHERE NOT EXISTS` de la consulta.
const alnum = String(l.lead_id || '').replace(/[^A-Za-z0-9]/g, '').toUpperCase();
const fid = 'FAC-R-' + (alnum.slice(-8) || 'SINLEAD');
// pago_token (S1 de la Tabla 11): mismo criterio que la rama normal de
// facturación — se genera acá porque el enlace se arma antes del INSERT.
// require puede estar bloqueado: con un UUID v4 en JS puro como respaldo, el flujo no se cae.
const uuidV4 = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});
let pagoToken;
try { pagoToken = require('crypto').randomUUID(); } catch (e) { pagoToken = uuidV4(); }
// Mismo criterio de importe que la rama normal: manda el precio que fijó el
// profesional; `presupuesto` es solo el respaldo de las propuestas viejas.
const monto = Number(l.precio_propuesto) > 0 ? Number(l.precio_propuesto) : Number(l.presupuesto) || 0;
const moneda = 'USD';
const pct = Number(leerEnv('COMISION_PLATAFORMA_PORCENTAJE', '1')) || 0;
const comision = Math.round(monto * (pct / 100) * 100) / 100;
const dias = Number(leerEnv('FACTURA_VENCIMIENTO_DIAS', '15')) || 15;
return [{ json: {
  lead_id: String(l.lead_id || ''),
  nombre: String(l.nombre || ''),
  email: String(l.email || ''),
  servicio: String(l.servicio || 'consultoria'),
  factura_id: fid,
  pago_token: pagoToken,
  monto: monto,
  moneda: moneda,
  comision_plataforma: comision,
  fecha_emision_iso: new Date().toISOString(),
  fecha_vencimiento_iso: new Date(Date.now() + dias * 86400000).toISOString()
} }];

// Mismo enlace propio que la rama de aceptación (Code - Resolver Link de
// Pago): la factura reconciliada entra al circuito de cobro y de
// recordatorios igual que si se hubiera emitido a tiempo.
const l = $('Code - Preparar Factura Reconciliada').first().json;
const leerEnv = (clave, porDefecto) => {
  try {
    const v = (typeof $env !== 'undefined' && $env) ? $env[clave] : undefined;
    return (v === undefined || v === null || v === '') ? porDefecto : String(v);
  } catch (e) { return porDefecto; }
};
const BASE = leerEnv('N8N_PUBLIC_URL', 'http://localhost:5678/').replace(/\/+$/, '');
const payUrl = BASE + '/webhook/pagar?f=' + encodeURIComponent(l.factura_id) + '&t=' + encodeURIComponent(l.pago_token);
return [{ json: Object.assign({}, l, { payUrl }) }];

