// Recordatorio (§4.3.1 / §4.9): un lead HOT/WARM quedó en NUEVO esperando
// que el profesional le fije precio, plazo y alcance. Sin LIMIT en la
// consulta: se avisa por cada lead que siga esperando, no solo el más
// viejo, y cada aviso lleva el total para que el profesional dimensione la
// cola sin entrar al tablero.
const items = $input.all();
// El total es el de la cola de cada espacio: cada aviso le llega a un
// desarrollador distinto.
const porEspacio = {};
for (const it of items) porEspacio[it.json.espacio_id] = (porEspacio[it.json.espacio_id] || 0) + 1;
const out = [];
for (const it of items) {
  const l = it.json;
  const horas = Math.floor(Number(l.horas_espera) || 0);
  const dias = Math.floor(horas / 24);
  const horaResto = horas % 24;
  const espera = dias > 0 ? (dias + ' día(s) y ' + horaResto + ' hora(s)') : (horas + ' hora(s)');
  out.push({ json: Object.assign({}, l, { espera_legible: espera, total_pendientes: porEspacio[l.espacio_id] }) });
}
return out;

