// Todo dato que se interpola en el HTML pasa por esc(): nombre, email, etc. los
// escribe quien completa el formulario público, y sin escapar alcanzaba para
// inyectar HTML en el correo o en el PDF que renderiza Gotenberg.
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
// Resume el UPDATE condicional de arriba en un solo aviso: con 0 filas no
// devuelve nada y el Telegram de abajo no llega a ejecutarse (sin esto,
// correr el cron sin facturas vencidas mandaría un mensaje vacío todos los
// días).
const items = $input.all();
if (!items.length) return [];
// Un resumen por espacio: cada desarrollador recibe sólo sus facturas.
const grupos = {};
for (const it of items) (grupos[it.json.espacio_id] = grupos[it.json.espacio_id] || []).push(it.json);
return Object.entries(grupos).map(([espacioId, fs]) => ({ json: {
  espacio_id: espacioId,
  cantidad: fs.length,
  detalle: fs.map((f) => esc(f.cliente) + ' — ' + esc(f.factura_id) + ' (' + esc(f.monto) + ' ' + esc(f.moneda) + ')').join('\n'),
} }));

