// Postgres - Insert Factura devuelve la fila insertada y descarta el binario
// que armó Code - Generar Factura HTML. Desde que la inserción pasó a correr
// antes del PDF (18-sep-2026), Gotenberg recibía un item sin
// factura_html_file y la rama se cortaba: ninguna factura salía por correo.
// Acá se vuelve a juntar la fila con el HTML.
const factura = $('Code - Generar Factura HTML').first();
return [{ json: $input.first().json, binary: factura.binary }];

// Enlace de pago de la factura (?f=<factura_id>&t=<pago_token>). Los dos
// datos van en el enlace que recibe el cliente; se validan acá sólo por forma
// y contra la base en el próximo nodo.
const q = $input.first().json.query || {};
const facturaId = String(q.f || '').trim();
const token = String(q.t || '').trim().toLowerCase();
const valido = /^FAC-[A-Z0-9-]{4,40}$/.test(facturaId) && /^[0-9a-f-]{36}$/.test(token);
return [{ json: { factura_id: valido ? facturaId : '', pago_token: valido ? token : '' } }];

// Qué hacer con el enlace de pago:
//  - 'stripe': crear la sesión de pago (destination charge a la cuenta del
//    desarrollador, con la comisión de la plataforma como application fee);
//  - 'redirigir': sin Stripe configurado, al modo de desarrollo (pago simulado);
//  - 'pagina': una explicación (enlace inválido, ya pagada, anulada, o el
//    desarrollador todavía no habilitó los cobros).
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const leerEnv = (clave, porDefecto) => {
  try {
    const v = (typeof $env !== 'undefined' && $env) ? $env[clave] : undefined;
    return (v === undefined || v === null || v === '') ? porDefecto : String(v);
  } catch (e) { return porDefecto; }
};
const f = $input.first().json || {};
const BASE = leerEnv('N8N_PUBLIC_URL', 'http://localhost:5678/').replace(/\/+$/, '');
const FRONT = leerEnv('FRONTEND_URL', 'http://localhost:3000').replace(/\/+$/, '');
const pagina = (status, titulo, texto) => ({ accion: 'pagina', status, location: '', html:
  "<!DOCTYPE html><html lang='es'><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>" + esc(titulo) + "</title></head>" +
  "<body style='font-family:Arial,Helvetica,sans-serif;background:#f5f2ea;color:#27272a;display:flex;align-items:center;justify-content:center;min-height:100vh;margin:0'>" +
  "<div style='background:#fff;border:1px solid #e4e0d4;padding:40px;max-width:440px;margin:16px'><h1 style='font-size:22px;margin:0 0 12px'>" + esc(titulo) + "</h1>" +
  "<p style='font-size:15px;line-height:1.6;color:#52525b;margin:0'>" + texto + "</p></div></body></html>" });
let salida;
if (!f.factura_id) {
  salida = pagina(404, 'Enlace inválido', 'Este enlace de pago no es válido. Usá el del correo de la factura.');
} else if (f.estado_pago === 'COBRADO') {
  salida = pagina(200, 'Factura pagada', 'La factura ' + esc(f.factura_id) + ' ya está pagada. ¡Gracias!');
} else if (f.estado_pago === 'ANULADA') {
  salida = pagina(410, 'Factura anulada', 'La factura ' + esc(f.factura_id) + ' fue anulada y no se puede pagar.');
} else if (!leerEnv('STRIPE_SECRET_KEY', '')) {
  salida = { accion: 'redirigir', status: 303, html: '', location: BASE + '/webhook/pago-confirmado?factura_id=' + encodeURIComponent(f.factura_id) + '&pago_token=' + encodeURIComponent(f.pago_token) + '&lead_id=' + encodeURIComponent(f.lead_id || '') };
} else if (!f.stripe_account_id || !f.stripe_cobros_activos) {
  salida = pagina(200, 'Pago online no disponible', esc(f.espacio_nombre || 'Quien te emitió la factura') + ' todavía no habilitó los pagos online. Respondé el correo de la factura para coordinar el pago.');
} else {
  const centavos = Math.round(Number(f.monto) * 100);
  const comision = Math.round(Number(f.comision_plataforma || 0) * 100);
  const svc = String(f.servicio || 'servicio').replace(/_/g, ' ');
  const campos = {
    mode: 'payment',
    'line_items[0][quantity]': '1',
    'line_items[0][price_data][currency]': String(f.moneda || 'USD').toLowerCase(),
    'line_items[0][price_data][unit_amount]': String(centavos),
    'line_items[0][price_data][product_data][name]': 'Factura ' + f.factura_id + ' — ' + svc,
    'payment_intent_data[application_fee_amount]': String(comision),
    'payment_intent_data[transfer_data][destination]': f.stripe_account_id,
    'payment_intent_data[metadata][factura_id]': f.factura_id,
    'metadata[factura_id]': f.factura_id,
    client_reference_id: f.factura_id,
    customer_email: String(f.email || ''),
    success_url: FRONT + '/pago-exitoso?factura=' + encodeURIComponent(f.factura_id),
    cancel_url: FRONT + '/pago-fallido?factura=' + encodeURIComponent(f.factura_id),
  };
  const form = Object.entries(campos).filter(([, v]) => v !== '').map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
  salida = { accion: 'stripe', status: 303, html: '', location: '', stripe_form: form, factura_id: f.factura_id };
}
return [{ json: salida }];

// Lo llama sólo el panel (/api/crm), con la credencial del panel y el
// espacio de la sesión de quien lo pide: el cuerpo no lo elige el navegador.
const b = $input.first().json.body || {};
const espacioId = String(b.espacio_id || '');
if (!/^[0-9a-f-]{36}$/i.test(espacioId)) throw new Error('espacio_id inválido');
return [{ json: { espacio_id: espacioId } }];

// Lo llama sólo el panel (/api/crm), con la credencial del panel y el
// espacio de la sesión de quien lo pide: el cuerpo no lo elige el navegador.
const b = $input.first().json.body || {};
const espacioId = String(b.espacio_id || '');
if (!/^[0-9a-f-]{36}$/i.test(espacioId)) throw new Error('espacio_id inválido');
return [{ json: { espacio_id: espacioId } }];

// Rechazo de un pedido desde el panel: el desarrollador no puede tomarlo y
// elige mandarlo a la bolsa (si el cliente lo autorizó) o descartarlo.
// /api/crm ya comprobó que el lead es de su espacio.
const b = $input.first().json.body || {};
const leerEnv = (clave, porDefecto) => {
  try {
    const v = (typeof $env !== 'undefined' && $env) ? $env[clave] : undefined;
    return (v === undefined || v === null || v === '') ? porDefecto : String(v);
  } catch (e) { return porDefecto; }
};
if (!b.lead_id || typeof b.lead_id !== 'string') throw new Error('Falta lead_id');
if (b.destino !== 'bolsa' && b.destino !== 'descartar') throw new Error('Destino invalido');
const resumen = typeof b.resumen === 'string' ? b.resumen.trim() : '';
// Mismo rango que el CHECK de bolsa_pedidos.resumen: mejor un error claro acá
// que un fallo de la consulta.
if (b.destino === 'bolsa' && (resumen.length < 20 || resumen.length > 2000)) {
  throw new Error('El resumen tiene que tener entre 20 y 2000 caracteres');
}
const entero = (clave, porDefecto) => {
  const n = parseInt(leerEnv(clave, String(porDefecto)), 10);
  return Number.isFinite(n) && n > 0 ? n : porDefecto;
};
return [{ json: {
  lead_id: b.lead_id,
  destino: b.destino,
  resumen,
  bolsa_tope: entero('BOLSA_TOPE', 5),
