} }];

// Correo al cliente cuando el desarrollador no puede tomar su pedido. Si lo
// mandó a la bolsa, le explica qué pasa ahora; si lo descartó, sólo le avisa.
const l = $input.first().json;
const esc = (s) => String(s ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
const SERVICIO = {
  desarrollo_web: 'desarrollo web', ecommerce: 'tienda online', app_movil: 'app móvil',
  automatizacion: 'automatización', marketing: 'marketing digital', seo: 'SEO',
  diseno_ui: 'diseño UX/UI', consultoria: 'consultoría', soporte: 'soporte',
};
let plataforma = 'FormularioLeads';
try { plataforma = ($env && $env.PLATAFORMA_NOMBRE) || plataforma; } catch (e) {}
const marca = l.espacio_nombre || plataforma;
const servicio = SERVICIO[l.servicio] || String(l.servicio || '').replaceAll('_', ' ');
const enBolsa = l.destino === 'bolsa' && Number(l.publicados) > 0;
const cuerpo = enBolsa
  ? `<p>Hola ${esc(l.nombre)},</p>
<p>Gracias por escribirnos. Esta vez no vamos a poder tomar tu proyecto de <b>${esc(servicio)}</b>.</p>
<p>Como lo autorizaste en el formulario, lo compartimos <b>sin tus datos de contacto</b> con otros desarrolladores de ${esc(plataforma)}. Si alguno se interesa, te escribimos con sus propuestas para que elijas. Tus datos sólo se comparten con quien elijas, y recién cuando lo elijas.</p>
<p>Saludos,<br><b>${esc(marca)}</b></p>`
  : `<p>Hola ${esc(l.nombre)},</p>
<p>Gracias por escribirnos. Esta vez no vamos a poder tomar tu proyecto de <b>${esc(servicio)}</b>.</p>
<p>Te deseamos mucha suerte con él.</p>
<p>Saludos,<br><b>${esc(marca)}</b></p>`;
return [{ json: {
  ...l,
  asunto: `Sobre tu consulta de ${servicio} — ${marca}`,
  cuerpo_html: cuerpo,
} }];

// Página donde el cliente elige entre las postulaciones de la bolsa
// (/elegir/<token>). El token es lo único que lo identifica: si no tiene
// forma de UUID, ni se consulta la base.
const q = $input.first().json.query || {};
const t = String(q.t || '').trim();
return [{ json: { token: /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(t) ? t : '' } }];

// El cliente elige una postulación. Token y postulación tienen que tener
// forma de UUID; el resto (que el pedido siga sin asignar y que la
// postulación sea de ese pedido) lo decide la consulta, con el pedido
// bloqueado para que dos clics no asignen dos veces.
const b = $input.first().json.body || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const token = String(b.t || '').trim();
const postulacion = String(b.postulacion_id || '').trim();
// Si el proyecto lo publicó un cliente, al elegir se crea el lead en el
// espacio elegido: el id se arma acá, con el mismo formato que Code -
// Normalizar Lead. En un pedido que ya tenía lead no se usa.
let azar;
try {
  azar = require('crypto').randomBytes(5).toString('hex').toUpperCase();
} catch (e) {
  azar = Math.random().toString(36).substring(2, 12).toUpperCase();
}
return [{ json: {
  token: UUID.test(token) ? token : '',
  postulacion_id: UUID.test(postulacion) ? postulacion : '',
  lead_nuevo: 'LD-' + Date.now() + '-' + azar,
} }];

// Dos correos al asignar un pedido de la bolsa: al cliente (sale con la
