// al desarrollador elegido (sale de la plataforma).
const l = $input.first().json;
const esc = (s) => String(s ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
const SERVICIO = {
  desarrollo_web: 'desarrollo web', ecommerce: 'tienda online', app_movil: 'app móvil',
  automatizacion: 'automatización', marketing: 'marketing digital', seo: 'SEO',
  diseno_ui: 'diseño UX/UI', consultoria: 'consultoría', soporte: 'soporte',
};
let plataforma = 'FormularioLeads';
try { plataforma = ($env && $env.PLATAFORMA_NOMBRE) || plataforma; } catch (e) {}
const servicio = SERVICIO[l.servicio] || String(l.servicio || '').replaceAll('_', ' ');
const precio = Number(l.precio_estimado).toLocaleString('es-AR');
const cliente = {
  email: l.email,
  espacio_nombre: l.espacio_nombre,
  espacio_email: l.espacio_email,
  asunto: `Elegiste a ${l.espacio_nombre} para tu proyecto de ${servicio}`,
  cuerpo_html: `<p>Hola ${esc(l.nombre)},</p>
<p>Listo: le pasamos tus datos a <b>${esc(l.espacio_nombre)}</b>, que te va a escribir con una propuesta formal. En su postulación estimó <b>US$ ${esc(precio)}</b> en <b>${esc(l.plazo)}</b>.</p>
<p>Si tenés alguna pregunta, respondé este correo y le llega directo.</p>
<p>Saludos,<br><b>${esc(plataforma)}</b></p>`,
};
const desarrollador = {
  email: l.espacio_email,
  // Sale de la plataforma, no del propio espacio.
  espacio_nombre: '',
  espacio_email: '',
  asunto: `Te eligieron para un proyecto de ${servicio}`,
  cuerpo_html: `<p>Hola ${esc(l.espacio_nombre)},</p>
<p><b>${esc(l.nombre)}</b> te eligió en la bolsa de proyectos para su proyecto de <b>${esc(servicio)}</b>.</p>
<p>Ya está en tu panel como pedido nuevo, con sus datos de contacto. Fijá los términos y mandale la propuesta.</p>
<p>Saludos,<br><b>${esc(plataforma)}</b></p>`,
};
return [cliente, desarrollador].filter((c) => c.email).map((c) => ({ json: { ...l, ...c } }));

